sys_ws_schema.schema:
{
  "type": "object",
  "description": "Fields to modify on an existing story. Include only fields that should be changed.",
  "properties": {
    "short_description": {
      "type": "string",
      "description": "New short description for the story"
    },
    "description": {
      "type": "string",
      "description": "New detailed description."
    },
    "acceptance_criteria": {
      "type": "string",
      "description": "New acceptance criteria."
    },
    "state": {
      "type": "string",
      "description": "Target story state. Supply the internal state value, such as the value returned by Get Story Details."
    },
    "priority": {
      "type": "string",
      "description": "Target priority. Supply the internal priority value."
    },
    "story_points": {
      "type": "number",
      "minimum": 0,
      "description": "Story point estimate"
    },
    "blocked": {
      "type": "boolean",
      "description": "Whether the story is blocked"
    },
    "project": {
      "type": "string",
      "description": "Project number, project name, or project sys_id."
    },
    "sprint": {
      "type": "string",
      "description": "Sprint number, sprint name, or sprint sys_id."
    },
    "assigned_to": {
      "type": "string",
      "description": "User name, user display name, or user sys_id.  Send an empty string to clear this field's existing value."
    },
    "assignment_group": {
      "type": "string",
      "description": "Assignment group name or sys_id.  Send an empty string to clear this field's existing value."
    },
    "work_notes": {
      "type": "string",
      "description": "Internal work note to append to the story. Adds a new journal entry."
    },
    "comments": {
      "type": "string",
      "description": "Comment to append to the story. Adds a new journal entry."
    }
  },
  "additionalProperties": false
}
